# watterson_1982_s_mle <- function(p){
#   stopifnot(length(p) >= 2)
#   stopifnot(all(p <= 1), all(p >= 0))
#   p_pen <- p[1:(length(p)-1)]
#   (p[length(p)]-p[1])/sum(p_pen*(1-p_pen))
